bool overlaps(const Segment& rhs) const noexcept {
		int64_t end = getEnd();
		int64_t rend = rhs.getEnd();
		return getStart() < rend && rhs.getStart() < end;
	}

void trim(const Segment& rhs) noexcept {
		if(!overlaps(rhs)) {
			return;
		}

		if(rhs.getStart() < start) {
			int64_t rend = rhs.getEnd();
			if(rend > getEnd()) {
				start = size = 0;
			} else {
				size -= rend - start;
				start = rend;
			}
			return;
		}

		size = rhs.getStart() - start;
	}

