int run() {
		setCurrentThreadPriority(threadPriority);
		while (true) {
			s.wait();
			if (stopping) {
				stopping = false;
				started = false;
				if (stopF) {
					stopF();
				}

				break;
			}

			dispatch();
		}
		return 0;
	}

bool dispatch() {
		if (!queue.try_pop(t)) {
			return false;
		}

		if (dispatchF) {
			dispatchF(*t);
		} else {
			(*t)();
		}

		delete t;
		return true;
	}

