		static void* operator new(size_t size) {

			return AllocManager::getInstance().allocate(size);
		}

		static void operator delete(void* m, size_t size) {

			AllocManager::getInstance().deallocate(m, size);
		}

	virtual ~FastAllocator() { }

	};

