	class concurrent_queue {
	public:
		bool push(const T& t) {
			WLock l(cs);
			queue.push_back(t);
			return true;
		}

		template <typename U>
		bool try_pop(U& t) {
			WLock l(cs);
			if (!queue.empty()) {
				t = std::move(queue.front());
				queue.pop_front();
				return true;
			}
			return false;
		}
	private:
		SharedMutex cs;
		std::deque<T> queue;
	};
